document.fonts.ready.then(async()=>{if([...document.fonts].some(f=>f.family.replaceAll('"','')==='bootstrap-icons')){try{await document.fonts.load('16px "bootstrap-icons"');if(document.fonts.check('16px "bootstrap-icons"'))document.body.classList.add('icons-ready');}catch{ /* Keep local icons. */ }}});





